  ]}),
  tools.subagent({
    description:'分类前半段收件箱',
    prompt:'你在 Obsidian 工作区 /Users/oyamahappa/Documents/Obsidian/Happa。请只读分析 收件箱.md 第36-1400行，按每个独立内容块/主题给出：简短标题、核心内容摘要、推荐目标文件夹（必须从现有顶层文件夹中选择，如 AI编程与Agent工具、网络安全、计算机与电子信息专业、大学学习与校园生活、求职就业与职场、考研与升学、科研论文与学科竞赛、系统工具与运维、沟通社交与自我提升、文化娱乐、个人杂记与待分类、编程与开发、GitHub、开发文档、准大一新生入学等）、建议新建或可能追加的文件名、是否可能与现有笔记重复。不要修改文件；返回结构化清单，覆盖全部独立主题。',
    run_in_background:true
  }),
  tools.subagent({
    description:'分类后半段收件箱',
    prompt:'你在 Obsidian 工作区 /Users/oyamahappa/Documents/Obsidian/Happa。请只读分析 收件箱.md 第1400-2710行，按每个独立内容块/主题给出：简短标题、核心内容摘要、推荐目标文件夹（必须从现有顶层文件夹中选择）、建议新建或可能追加的文件名、是否可能与现有笔记重复。重点识别内容边界，即使同一段包含多个主题也要拆分。不要修改文件；返回结构化清单，覆盖全部独立主题。',
    run_in_background:true
  }),
  tools.subagent({
    description:'检查现有笔记重复项',
    prompt:'请只读检查 /Users/oyamahappa/Documents/Obsidian/Happa 的现有 Markdown 文件和文件夹结构，重点关注哪些文件可接收 收件箱.md 待整理内容、哪些主题已有对应笔记、哪些应新建文件。返回按目标文件夹分组的建议，并指出重复/合并风险。不要修改文件。',
    run_in_background:true
  })
]);
return results.map((r,i)=>({index:i,kind:r.kind,jobId:(r as any).jobId,subagentId:(r as any).subagentId}));","description":"Plan inbox classification with parallel reviewers"}

