{"code":"const [a,b] = await Promise.all([
  tools.read({file_path:'收件箱.md',offset:1,limit:2000}),
  tools.read({file_path:'收件箱.md',offset:2001,limit:2000})
]);
const lines = [...a.lines,...b.lines].map(x=>({n:x.number,t:x.text}));
const isHeading = (t)=>/^(#{1,6} |\*\*[^*]+\*\*$)/.test(t.trim());
const heads = lines.filter(x=>x.n>=36 && isHeading(x.t));
const rows = heads.map((h,i)=>{
  const end = (heads[i+1]?.n ?? 2711)-1;
  const body = lines.filter(x=>x.n>h.n && x.n<=Math.min(end,h.n+5)).map(x=>x.t.trim()).filter(Boolean).join(' ');
  return {start:h.n,end,title:h.t.trim(),preview:body.slice(0,260)};
});
return rows;","description":"Inventory all inbox topic boundaries"}

