{"code":"const inboxParts = await Promise.all([
  tools.read({file_path:'收件箱.md',offset:1,limit:2000}),
  tools.read({file_path:'收件箱.md',offset:2001,limit:710})
]);
const all = [...inboxParts[0].lines,...inboxParts[1].lines].sort((a,b)=>a.number-b.number);
const raw = new Map(all.map(x=>[x.number,x.text]));
const block = (from,to) => {
  const text = Array.from({length:to-from+1},(_,i)=>raw.get(from+i) ?? '').join('\n');
  return text
    .replace(/\[span_\d+\]\(start_span\)\[span_\d+\]\(end_span\)/g,'')
    .replace(/\[span_\d+\]\(start_span\)/g,'')
    .replace(/\[span_\d+\]\(end_span\)/g,'')
    .replace(/\s+$/,'');
};
const section = (title, from, to) => `### ${title}\n\n${block(from,to)}`;
const header = (title, description, source) => `# ${title}\n\n> ${description}\n\n> 原始来源：收件箱.md（原“待整理”第 ${source} 行）。\n\n---\n\n`;
const notes = new Map<string,string>();
const add = (path, title, description, source, sections) => notes.set(path, header(title,description,source)+sections.join('\n\n---\n\n'));

add('AI编程与Agent工具/Firecrawl网页抓取与LLM数据提取.md','Firecrawl 网页抓取与 LLM 数据提取','面向 AI 应用、LLM 与 Agent 的开源网页抓取和结构化提取工具。项目链接与用途按收件箱原文归档。','39–41',[block(39,41)]);
add('AI编程与Agent工具/Cloudflare Computer开源AI运行环境.md','Cloudflare Computer：开源 AI 运行环境','把可操作的 Linux 工作区放入 Cloudflare Workers 的方案；安装命令、持久化能力和工具边界仍应以官方文档为准。','101–116',[block(101,116),'> **核验提醒：** npm 包名、工作区容量、持久化和权限说明可能随版本变化，部署前请核对官方仓库与 Cloudflare 文档。']);
add('AI编程与Agent工具/Android闲置手机部署OpenClaw与本地知识库.md','Android 闲置手机部署 OpenClaw 与本地知识库','记录使用旧 Android 手机、Termux、Ubuntu proot 和向量库搭建个人 Agent/知识库的完整思路。','207–447',[block(207,447),'> **安全提醒：** API 密钥、推送凭据和局域网服务不要直接暴露到公网；部署前确认手机、账户和数据均属于自己或已获授权。']);
add('AI编程与Agent工具/DeepSeek DSH插件生态与安装避坑.md','DeepSeek DSH 插件生态与安装避坑','把收件箱两处近重复的 DSH 插件清单合并为一个待核验目录，避免把第三方插件宣传当作官方能力。','1041–1065、1125–1161',[block(1041,1065),'> 收件箱第 1125–1161 行为同主题重复块，已不再重复抄录。', '## 核验与安全边界\n\n- 安装前核对项目仓库、维护者、版本兼容性、权限范围和许可证。\n- 对 memory、flow、browser、workflow 等可能修改本地文件或联网的插件，先在隔离环境试用。\n- “必装/推荐”只是来源观点，不代表 DSH 官方背书。']);
add('AI编程与Agent工具/AI Agent安全、上下文与持久记忆.md','AI Agent 安全、上下文与持久记忆','合并 Agent 架构、可逆性检查、上下文交接、持久记忆文件组织和文档读取规则。','1822–1855、2063–2073、1460–1476',[section('安全护栏与可逆性检查',1822,1837),section('持久记忆文件系统',1839,1855),section('上下文工程规范',2063,2073),section('Codex 与 Obsidian 记忆联动提示词',1460,1476),'> **实践建议：** 删除、覆盖、批量修改、生产变更、数据库写入和发信前，先让 Agent 明确影响范围、不可逆边界与恢复方案，并等待人工确认。']);
add('AI编程与Agent工具/自治Agent商业场景与Prompt.md','自治 Agent 商业场景与 Prompt','归档浏览器代办、商业分析、获客实验和 eBay 挂闲置等场景；成本、可行性和平台条款需要单独核实。','1792–1819、1915–1919',[section('Agent 场景与 Prompt 共性',1792,1819),section('Astra eBay 自动挂闲置成本记录',1915,1919)]);
add('AI编程与Agent工具/NVIDIA免费API与Agent接入.md','NVIDIA 免费 API 与 Agent 接入','记录 build.nvidia.com API Key、Base URL 和常见 Agent/编辑器接入方式；额度和有效期仅作来源快照。','1894–1912',[block(1894,1912),'> **核验提醒：** 频率限制、有效期、可用模型和服务条款会变动，以 NVIDIA 官方控制台和文档为准；不要把 API Key 提交到 Git。']);
add('AI编程与Agent工具/大模型基准测试与降智甄别.md','大模型基准测试与“降智”甄别','记录以 SVG/HTML 任务比较模型和推理档位的实验想法；单个任务只能提供线索，不能据此断言模型路由或能力下降。','1940–1954',[block(1940,1954),'> **解释边界：** “思考词”“输出风格”或一次基准结果都可能受提示词、采样参数和服务端策略影响，结论应通过可重复、多任务测试验证。']);
